const _raw = $input.first().json;
const data = (_raw && typeof _raw === 'object' && _raw.body && typeof _raw.body === 'object') ? _raw.body : _raw;
const name = (data.name || 'there').toString().trim();
const service = (data.service || 'general').toString().toLowerCase();
const message = (data.message || '').toString().toLowerCase();
const phone = (data.phone || '').toString();
const email = (data.email || '').toString();

const hotKeywords = ['urgent','asap','today','tomorrow','price','cost','book','appointment','demo','interested','call me','quote','emi','discount'];
const warmKeywords = ['info','details','timing','location','services','offer','how','when','where'];
let score = 30;
for (const k of hotKeywords) { if (message.includes(k)) score += 12; }
for (const k of warmKeywords) { if (message.includes(k)) score += 6; }
if (phone) score += 10;
if (email) score += 8;
if (service !== 'general') score += 5;
score = Math.min(score, 99);

const tier = score >= 70 ? 'HOT' : score >= 45 ? 'WARM' : 'COLD';
const replies = {
  HOT: 'Hi ' + name + '! Thanks for reaching out about ' + service + ' — your enquiry is marked PRIORITY. Our team will call you within 30 minutes. Anything specific I can help with right away?',
  WARM: 'Hi ' + name + '! Thanks for your interest in ' + service + '. We will get back within 2 business hours. Want me to book a free 15-min consultation for you?',
  COLD: 'Hi ' + name + '! Thanks for contacting us about ' + service + '. We will review your message and respond within 24 hours.'
};

return [{ json: {
  name: name,
  phone: phone,
  email: email,
  service: service,
  message: data.message || '',
  score: score,
  tier: tier,
  reply: replies[tier],
  nextAction: tier === 'HOT' ? 'Call within 30 min' : tier === 'WARM' ? 'Follow up within 2 hrs' : 'Follow up within 24 hrs',
  receivedAt: new Date().toISOString()
}}];
